package com.capytutor.core.session

/**
 * Everything Capy says that is not generated by the model. Romanian, "tu", short sentences,
 * never "Greșit", never a timer. Kept in one place so the copy can be reviewed at a glance.
 */
object CapyLines {
    fun intro(title: String, ideas: Int) =
        "Lecția „$title” are $ideas idei cheie. Când ești gata, hai să începem!"

    const val ASK_RETELL = "Povestește-mi cu cuvintele tale tot ce ții minte."
    const val RETELL_EMPTY = "Spune-mi măcar un lucru pe care ți-l amintești."
    const val RETELL_NOTHING = "E în regulă. Le descoperim împreună, pe rând."

    fun coverage(known: Int, total: Int) = when {
        known == total -> "Ai povestit toate ideile! Hai să trecem la test."
        known == 0 -> "Hai să le căutăm împreună, pe rând."
        else -> "Ai ținut minte $known din $total idei. Hai să le căutăm împreună pe celelalte."
    }

    const val NEXT_IDEA = "Hai la următoarea idee."
    const val NOT_YET_LOOK_TOGETHER = "Încă nu. Hai să ne uităm împreună."
    const val NO_PROBLEM_CLUE = "Nicio problemă. Uite un indiciu:"
    const val SAY_IT_BACK = "Spune-mi și tu, cu cuvintele tale."
    const val RECALLED = "Da, ți-ai amintit! Indiciul te-a ajutat."
    const val SAID_IT_BACK = "Bravo, acum ai spus-o chiar tu!"
    const val TRIED_SAY_BACK = "Mulțumesc că ai încercat. O repetăm la test."
    const val SKIP_SAY_BACK = "E în regulă. O întâlnim din nou la test."
    const val DISPUTE_NOTED = "Bine, am notat. Un părinte se va uita."

    const val TEST_START = "Acum un mic test: câte o întrebare pentru fiecare idee."
    const val CORRECT = "Corect!"
    fun notYetAnswer(answer: String) = "Încă nu. Răspunsul este: ${answer.trimEnd('.', ' ')}."
    fun unjudged(answer: String) = "Hai să vedem răspunsul: ${answer.trimEnd('.', ' ')}."

    fun score(correct: Int, total: Int) = "$correct din $total"
    fun summaryFallback(correct: Int, total: Int) =
        "Ai răspuns bine la $correct din $total întrebări. Mulțumesc că ai lucrat cu mine!"

    const val PAUSE = "Capy e puțin obosit. Continuăm mai târziu?"
    const val RESUMED = "Am revenit! Continuăm de unde am rămas."
    const val DONE = "Gata pe azi. Pe curând!"
}
